// Sky dome, clouds and a handful of distant birds — all procedural.

import * as THREE from 'three';

const SKY_VERTEX = /* glsl */ `
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const SKY_FRAGMENT = /* glsl */ `
  precision highp float;

  uniform vec3 uZenith;
  uniform vec3 uHorizon;
  uniform vec3 uSunDir;
  uniform vec3 uSunColor;

  varying vec3 vDir;

  void main() {
    vec3 d = normalize(vDir);
    float h = clamp(d.y, 0.0, 1.0);

    vec3 col = mix(uHorizon, uZenith, pow(h, 0.52));

    float s = max(dot(d, normalize(uSunDir)), 0.0);
    col += uSunColor * (pow(s, 1500.0) * 3.4 + pow(s, 90.0) * 0.55 + pow(s, 8.0) * 0.22);

    // just under the horizon keep the haze colour so the ocean fog blends in
    col = mix(col, uHorizon, smoothstep(0.0, -0.09, d.y));

    gl_FragColor = vec4(col, 1.0);
  }
`;

/** Soft puffy cloud sprite drawn on a canvas. */
function makeCloudTexture() {
  const w = 256;
  const h = 128;
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  const blobs = [
    [64, 78, 42], [100, 62, 52], [138, 70, 50], [176, 80, 40],
    [118, 88, 36], [84, 90, 30], [156, 92, 32], [204, 88, 26],
  ];
  for (const [x, y, r] of blobs) {
    const g = ctx.createRadialGradient(x, y, r * 0.1, x, y, r);
    g.addColorStop(0, 'rgba(255,255,255,0.95)');
    g.addColorStop(0.55, 'rgba(255,252,246,0.55)');
    g.addColorStop(1, 'rgba(255,250,242,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  return tex;
}

function createClouds() {
  const group = new THREE.Group();
  const tex = makeCloudTexture();

  for (let i = 0; i < 14; i++) {
    const mat = new THREE.SpriteMaterial({
      map: tex,
      transparent: true,
      depthWrite: false,
      fog: false,
      opacity: 0.5 + Math.random() * 0.32,
      color: new THREE.Color().setHSL(0.09, 0.5, 0.92 - Math.random() * 0.06),
    });
    const sprite = new THREE.Sprite(mat);
    const a = Math.random() * Math.PI * 2;
    const r = 130 + Math.random() * 190;
    sprite.position.set(Math.cos(a) * r, 46 + Math.random() * 95, Math.sin(a) * r);
    const s = 44 + Math.random() * 78;
    sprite.scale.set(s, s * (0.38 + Math.random() * 0.14), 1);
    sprite.userData.speed = 0.5 + Math.random() * 1.4;
    group.add(sprite);
  }
  return group;
}

function createBirds() {
  const group = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x3d4d58, fog: false, side: THREE.DoubleSide });

  const wingGeo = new THREE.PlaneGeometry(1.5, 0.3, 2, 1);
  wingGeo.translate(0.75, 0, 0);

  for (let i = 0; i < 6; i++) {
    const bird = new THREE.Group();

    const left = new THREE.Mesh(wingGeo, mat);
    const right = new THREE.Mesh(wingGeo, mat);
    right.scale.x = -1;
    bird.add(left, right);

    const body = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), mat);
    body.scale.set(0.8, 0.8, 2.0);
    bird.add(body);

    const a = Math.random() * Math.PI * 2;
    const radius = 26 + Math.random() * 70;
    bird.userData = {
      centerX: -20 + Math.random() * 60,
      centerZ: -40 + Math.random() * 60,
      radius,
      angle: a,
      speed: (0.02 + Math.random() * 0.035) * (Math.random() < 0.5 ? -1 : 1),
      height: 24 + Math.random() * 26,
      flapPhase: Math.random() * Math.PI * 2,
      flapSpeed: 6 + Math.random() * 3,
      wings: [left, right],
    };
    bird.scale.setScalar(1.1 + Math.random() * 0.7);
    group.add(bird);
  }
  return group;
}

export function createSky({ sunDir }) {
  const uniforms = {
    uZenith: { value: new THREE.Color(0x2a67b4) },
    uHorizon: { value: new THREE.Color(0xd9e7ef) },
    uSunDir: { value: sunDir.clone() },
    uSunColor: { value: new THREE.Color(0xffd6a0) },
  };

  const geometry = new THREE.SphereGeometry(900, 48, 32);
  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: SKY_VERTEX,
    fragmentShader: SKY_FRAGMENT,
    side: THREE.BackSide,
    depthWrite: false,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;

  const clouds = createClouds();
  const birds = createBirds();

  return {
    mesh,
    group: (() => {
      const g = new THREE.Group();
      g.add(mesh, clouds, birds);
      return g;
    })(),
    update(t, dt) {
      // clouds drift slowly and wrap around
      for (const sprite of clouds.children) {
        sprite.position.x += sprite.userData.speed * dt;
        if (sprite.position.x > 340) sprite.position.x = -340;
      }

      // distant birds loop over the water
      for (const bird of birds.children) {
        const u = bird.userData;
        u.angle += u.speed * dt;
        const x = u.centerX + Math.cos(u.angle) * u.radius;
        const z = u.centerZ + Math.sin(u.angle) * u.radius;
        bird.position.set(x, u.height + Math.sin(t * 0.6 + u.flapPhase) * 1.6, z);

        const vx = -Math.sin(u.angle) * Math.sign(u.speed);
        const vz = Math.cos(u.angle) * Math.sign(u.speed);
        bird.rotation.y = Math.atan2(vx, vz);

        const flap = Math.sin(t * u.flapSpeed + u.flapPhase);
        const [left, right] = u.wings;
        left.rotation.z = 0.25 + flap * 0.65;
        right.rotation.z = -0.25 - flap * 0.65;
      }
    },
  };
}

// CPU particle system used for the spray and foam kicked up by the board.
// One THREE.Points object with per-particle size and alpha attributes.

import * as THREE from 'three';

const VERTEX = /* glsl */ `
  attribute float aSize;
  attribute float aAlpha;

  uniform float uPixelRatio;

  varying float vAlpha;

  void main() {
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * uPixelRatio * 320.0 / max(-mv.z, 0.1);
    gl_Position = projectionMatrix * mv;
  }
`;

const FRAGMENT = /* glsl */ `
  precision mediump float;

  uniform sampler2D uMap;
  varying float vAlpha;

  void main() {
    float a = texture2D(uMap, gl_PointCoord).a * vAlpha;
    if (a < 0.003) discard;
    gl_FragColor = vec4(vec3(0.94, 0.98, 1.0), a);
  }
`;

function makeDropletTexture() {
  const size = 64;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0.0, 'rgba(255,255,255,1)');
  g.addColorStop(0.42, 'rgba(255,255,255,0.72)');
  g.addColorStop(1.0, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function createSpray({ max = 1000 } = {}) {
  const positions = new Float32Array(max * 3);
  const sizes = new Float32Array(max);
  const alphas = new Float32Array(max);
  const velocities = new Float32Array(max * 3);
  const life = new Float32Array(max);
  const maxLife = new Float32Array(max);
  const baseSize = new Float32Array(max);
  const baseAlpha = new Float32Array(max);
  let cursor = 0;

  const geometry = new THREE.BufferGeometry();
  const posAttr = new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage);
  const sizeAttr = new THREE.BufferAttribute(sizes, 1).setUsage(THREE.DynamicDrawUsage);
  const alphaAttr = new THREE.BufferAttribute(alphas, 1).setUsage(THREE.DynamicDrawUsage);
  geometry.setAttribute('position', posAttr);
  geometry.setAttribute('aSize', sizeAttr);
  geometry.setAttribute('aAlpha', alphaAttr);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uMap: { value: makeDropletTexture() },
      uPixelRatio: { value: 1 },
    },
    vertexShader: VERTEX,
    fragmentShader: FRAGMENT,
    transparent: true,
    depthWrite: false,
  });

  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;

  function emit(x, y, z, vx, vy, vz, size, alpha, lifetime) {
    const i = cursor;
    cursor = (cursor + 1) % max;

    positions[i * 3] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = z;
    velocities[i * 3] = vx;
    velocities[i * 3 + 1] = vy;
    velocities[i * 3 + 2] = vz;
    life[i] = lifetime;
    maxLife[i] = lifetime;
    baseSize[i] = size;
    baseAlpha[i] = alpha;
    sizes[i] = size;
    alphas[i] = alpha;
  }

  function update(dt) {
    for (let i = 0; i < max; i++) {
      if (life[i] <= 0) {
        alphas[i] = 0;
        continue;
      }
      life[i] -= dt;

      if (life[i] <= 0) {
        alphas[i] = 0;
        continue;
      }

      const drag = Math.exp(-1.15 * dt);
      velocities[i * 3] *= drag;
      velocities[i * 3 + 1] = velocities[i * 3 + 1] * drag - 7.6 * dt;
      velocities[i * 3 + 2] *= drag;

      positions[i * 3] += velocities[i * 3] * dt;
      positions[i * 3 + 1] += velocities[i * 3 + 1] * dt;
      positions[i * 3 + 2] += velocities[i * 3 + 2] * dt;

      const progress = 1 - life[i] / maxLife[i];
      const fadeIn = Math.min(1, progress * 7.0);
      alphas[i] = baseAlpha[i] * fadeIn * (1 - progress) * (1 - progress * 0.25);
      sizes[i] = baseSize[i] * (1 + progress * 1.1);
    }

    posAttr.needsUpdate = true;
    sizeAttr.needsUpdate = true;
    alphaAttr.needsUpdate = true;
  }

  function setPixelRatio(ratio) {
    material.uniforms.uPixelRatio.value = ratio;
  }

  return { points, emit, update, setPixelRatio };
}

