    const foot = new THREE.Mesh(footGeometry(), materials.leg);
    foot.rotation.y = -Math.PI / 2;
    foot.position.set(0.04, 0.012, z);
    root.add(foot);

    const shadow = circleShadow(0.19, 0.22);
    shadow.position.set(0.1, 0.004, z);
    root.add(shadow);
  }

